import json
import yaml

from prompty.model import ContentPart

def test_load_json_contentpart():
    json_data = r'''
    {
      "kind": "text",
      "value": "Hello, world!"
    }
    '''
    data = json.loads(json_data, strict=False)
    instance = ContentPart.load(data)
    assert instance is not None
    assert instance.kind == "text"

def test_load_yaml_contentpart():
    yaml_data = r'''
    kind: text
    value: Hello, world!

    '''
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = ContentPart.load(data)
    assert instance is not None
    assert instance.kind == "text"

def test_roundtrip_json_contentpart():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r'''
    {
      "kind": "text",
      "value": "Hello, world!"
    }
    '''
    original_data = json.loads(json_data, strict=False)
    instance = ContentPart.load(original_data)
    saved_data = instance.save()
    reloaded = ContentPart.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "text"

def test_to_json_contentpart():
    """Test that to_json produces valid JSON."""
    json_data = r'''
    {
      "kind": "text",
      "value": "Hello, world!"
    }
    '''
    data = json.loads(json_data, strict=False)
    instance = ContentPart.load(data)
    json_output = instance.to_json()
    assert json_output is not None
    parsed = json.loads(json_output)
    assert isinstance(parsed, dict)

def test_to_yaml_contentpart():
    """Test that to_yaml produces valid YAML."""
    json_data = r'''
    {
      "kind": "text",
      "value": "Hello, world!"
    }
    '''
    data = json.loads(json_data, strict=False)
